/* MSKBA Arena v3 — desktop scroll scene + existing ball handoff.
 * READY TO PASTE ONCE AT THE END OF FILAMENT > HOME PAGE > JS.
 * NO Python, no editing existing JS, no new ball DOM element.
 * Scope: >= 1100px. The existing script owns tablet/mobile.
 * ID: MSKBA_ARENA_V3_READY_20261102
 */
(() => {
  'use strict';
  const scene = document.getElementById('venues-scene');
  const hero = document.querySelector('.mskba-hero-scene');
  const slider = hero?.querySelector('[data-mskba-hero-slider]')
    || hero?.querySelector('.mskba-hero-slider');
  const ball = document.querySelector('.mskba-rolling-ball');
  const visual = scene?.querySelector('.mskba-v3-venues__foreground');
  const marker = scene?.querySelector('.mskba-venues-scene__ball-target');
  if (!scene || scene.dataset.arenaV3Ready === '1') return;
  scene.dataset.arenaV3Ready = '1';

  const desktop = window.matchMedia('(min-width: 1100px)');
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
  const clamp = (n, a = 0, b = 1) => Math.max(a, Math.min(b, n));
  let queued = 0;

  function drawEntrance() {
    if (!desktop.matches) {
      for (const prop of ['--v3-ghost-entry-x', '--v3-defender-entry-y', '--v3-shooter-entry-y']) {
        scene.style.removeProperty(prop);
      }
      return;
    }
    const viewport = Math.max(1, window.innerHeight);
    const top = window.scrollY + scene.getBoundingClientRect().top;
    const start = Math.max(0, top - viewport * 0.85);
    const finish = Math.max(start + Math.max(220, viewport * 0.36), top - viewport * 0.18);
    const progress = reducedMotion.matches ? 1 : clamp((window.scrollY - start) / (finish - start));
    const remaining = 1 - progress;
    scene.style.setProperty('--v3-ghost-entry-x', (24 * remaining).toFixed(3) + 'vw');
    scene.style.setProperty('--v3-defender-entry-y', (30 * remaining).toFixed(3) + '%');
    scene.style.setProperty('--v3-shooter-entry-y', (20 * remaining).toFixed(3) + '%');
  }

  // Paint the same existing sprite after the legacy page handler has run.
  // This also restores visibility when the old handoff points to venues-intro.
  // A single ball moves between Hero and the new Venues visual space.
  function drawBall() {
    if (!desktop.matches || !slider || !ball || !visual || !marker) return;
    const sliderRect = slider.getBoundingClientRect();
    if (sliderRect.width <= 0 || sliderRect.height <= 0) return;

    const pageHeroTop = window.scrollY + sliderRect.top;
    const animationStart = Math.max(0, pageHeroTop - window.innerHeight * 0.8);
    const heroDuration = Math.min(360, Math.max(270, sliderRect.height * 0.48)) * 0.7;
    const stageEnd = animationStart + heroDuration;
    const scroll = window.scrollY;

    ball.style.display = 'block';
    ball.style.visibility = 'visible';
    ball.style.opacity = '1';
    ball.style.pointerEvents = 'none';
    ball.style.setProperty('--ball-tile-size', '195px');

    if (scroll <= stageEnd || reducedMotion.matches && scroll <= animationStart) {
      const p = reducedMotion.matches ? 1 : clamp((scroll - animationStart) / heroDuration);
      if (ball.parentElement !== slider) slider.appendChild(ball);
      const x = 255 + (760 - 255) * p;
      const y = 440 + (890 - 440) * p;
      const light = p * p * (3 - 2 * p);
      const steps = Math.floor(p * 16);
      const frame = p >= 1 ? 0 : (16 - (steps % 16)) % 16;
      ball.style.left = (x / 10).toFixed(3) + '%';
      ball.style.top = (y / 10).toFixed(3) + '%';
      ball.style.setProperty('--ball-scale', (0.22 + 0.78 * p).toFixed(4));
      ball.style.setProperty('--ball-brightness', (0.57 + 0.45 * light).toFixed(4));
      ball.style.setProperty('--ball-saturation', (0.74 + 0.26 * light).toFixed(4));
      ball.style.setProperty('--ball-frame-x', ((frame % 4) * 100 / 3).toFixed(4) + '%');
      ball.style.setProperty('--ball-frame-y', (Math.floor(frame / 4) * 100 / 3).toFixed(4) + '%');
      return;
    }

    const height = scene.getBoundingClientRect().height;
    const length = Math.max(220, Math.min(440, height * 0.46));
    const remainingPage = Math.max(0,
      document.documentElement.scrollHeight - window.innerHeight - stageEnd);
    const duration = Math.max(1, Math.min(length, remainingPage));
    const p = reducedMotion.matches ? 1 : clamp((scroll - stageEnd) / duration);

    const spaceRect = visual.getBoundingClientRect();
    const targetRect = marker.getBoundingClientRect();
    const startX = sliderRect.left - spaceRect.left + sliderRect.width * 0.76;
    const startY = sliderRect.top - spaceRect.top + sliderRect.height * 0.89;
    const endX = targetRect.left - spaceRect.left;
    const endY = targetRect.top - spaceRect.top;
    const x = startX + (endX - startX) * p;
    const y = startY + (endY - startY) * p;

    if (ball.parentElement !== visual) visual.appendChild(ball);
    ball.style.left = x.toFixed(2) + 'px';
    ball.style.top = y.toFixed(2) + 'px';
    ball.style.setProperty('--ball-scale', (1 - 0.52 * p).toFixed(4));
    ball.style.setProperty('--ball-brightness', (1.02 - 0.1 * p).toFixed(4));
    ball.style.setProperty('--ball-saturation', '1');
    const frame = p >= 1 ? 0 : Math.floor(p * 16) % 16;
    ball.style.setProperty('--ball-frame-x', ((frame % 4) * 100 / 3).toFixed(4) + '%');
    ball.style.setProperty('--ball-frame-y', (Math.floor(frame / 4) * 100 / 3).toFixed(4) + '%');
  }

  function draw() {
    queued = 0;
    drawEntrance();
    drawBall();
  }
  function schedule() {
    if (!queued) queued = window.requestAnimationFrame(draw);
  }
  // Register after the existing ball script: last writer controls its position.
  window.addEventListener('scroll', schedule, { passive: true });
  window.addEventListener('resize', schedule, { passive: true });
  desktop.addEventListener?.('change', schedule);
  reducedMotion.addEventListener?.('change', schedule);
  draw();
})();

