/* Arena v3 scroll entrants: the rolling-ball controller above is the
 * ONLY writer of ball placement and DOM parent (Hero ↔ Venues).
 */
(() => {
  'use strict';
  const scene = document.getElementById('venues-scene');
  if (!scene || scene.dataset.arenaV3EntranceReady === '1') return;
  scene.dataset.arenaV3EntranceReady = '1';
  const desktop = window.matchMedia('(min-width: 1100px)');
  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)');
  const clamp = n => Math.max(0, Math.min(1, n));
  let frame = 0;
  function paint() {
    frame = 0;
    if (!desktop.matches) {
      for (const property of ['--v3-ghost-entry-x', '--v3-defender-entry-y', '--v3-shooter-entry-y']) {
        scene.style.removeProperty(property);
      }
      return;
    }
    const vh = Math.max(1, window.innerHeight);
    const sceneTop = window.scrollY + scene.getBoundingClientRect().top;
    const start = Math.max(0, sceneTop - vh * .85);
    const finish = Math.max(start + Math.max(220, vh * .36), sceneTop - vh * .18);
    const p = reduced.matches ? 1 : clamp((window.scrollY - start) / (finish - start));
    const remaining = 1 - p;
    scene.style.setProperty('--v3-ghost-entry-x', (24 * remaining).toFixed(3) + 'vw');
    scene.style.setProperty('--v3-defender-entry-y', (30 * remaining).toFixed(3) + '%');
    scene.style.setProperty('--v3-shooter-entry-y', (20 * remaining).toFixed(3) + '%');
  }
  function schedule() { if (!frame) frame = requestAnimationFrame(paint); }
  window.addEventListener('scroll', schedule, { passive: true });
  window.addEventListener('resize', schedule, { passive: true });
  desktop.addEventListener?.('change', schedule);
  reduced.addEventListener?.('change', schedule);
  paint();
})();
